static
void kernel_lu(int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  int ii, jj, kk, jend, kend;
  const int B = 32; // tile size

  for (i = 0; i < _PB_N; i++) {
    /* First loop: compute L entries for row i (j < i) */
    for (j = 0; j < i; j += B) {
      jend = (j + B < i) ? j + B : i;
      for (k = 0; k < jend; k++) {
        DATA_TYPE aik = A[i][k];
        int jstart = (k + 1 > j) ? k + 1 : j;
        #pragma omp simd
        for (jj = jstart; jj < jend; jj++) {
          A[i][jj] -= aik * A[k][jj];
        }
      }
      #pragma omp simd
      for (jj = j; jj < jend; jj++) {
        A[i][jj] /= A[jj][jj];
      }
    }

    /* Second loop: update U entries for row i (j >= i) */
    #pragma omp parallel for schedule(static) default(none) shared(A, n, i) private(j, jend, k, jj)
    for (j = i; j < n; j += B) {
      jend = (j + B < n) ? j + B : n;
      for (k = 0; k < i; k++) {
        DATA_TYPE aik = A[i][k];
        #pragma omp simd
        for (jj = j; jj < jend; jj++) {
          A[i][jj] -= aik * A[k][jj];
        }
      }
    }
  }
#pragma endscop
}

