    #pragma omp parallel for schedule(static) default(none) shared(A, n, i) private(j, j0, j1, k, jj)
    for (j = i; j < _PB_N; j += B) {
      j0 = j;
      j1 = j + B;
      if (j1 > _PB_N) j1 = _PB_N;
      for (k = 0; k < i; k++) {
